  localparam logic [63:0] ID_AA64ISAR3_VAL = 64'h0000_0000_1000_0010;
  localparam logic [63:0] ID_AA64MMFR4_VAL = 64'h0000_0000_0000_0100;
  localparam logic [63:0] ID_PFR0_A32_VAL = 64'h0000_0000_1102_0131;
  localparam logic [63:0] ID_PFR1_A32_VAL = 64'h0000_0000_0001_0001;
  localparam logic [63:0] ID_AFR0_A32_VAL = 64'h0;
  localparam logic [63:0] ID_MMFR0_A32_VAL = 64'h0000_0000_1010_1105;
  localparam logic [63:0] ID_MMFR1_A32_VAL = 64'h0000_0000_4000_0000;
  localparam logic [63:0] ID_MMFR2_A32_VAL = 64'h0000_0000_0126_0000;
  localparam logic [63:0] ID_MMFR3_A32_VAL = 64'h0000_0000_0212_2211;
  localparam logic [63:0] ID_ISAR0_A32_VAL = 64'h0000_0000_0210_1110;
  localparam logic [63:0] ID_ISAR1_A32_VAL = 64'h0000_0000_1311_2111;
  localparam logic [63:0] ID_ISAR2_A32_VAL = 64'h0000_0000_2123_2042;
  localparam logic [63:0] ID_ISAR3_A32_VAL = 64'h0000_0000_0111_2131;
  localparam logic [63:0] ID_ISAR4_A32_VAL = 64'h0000_0000_0001_1142;
  localparam logic [63:0] ID_ISAR5_A32_VAL = 64'h0000_0000_1101_1121;
  localparam logic [63:0] ID_ISAR5_A32_NOFP_VAL = 64'h0000_0000_0001_0001;
  localparam logic [63:0] ID_MMFR4_A32_VAL = 64'h0000_0000_2002_1110;
  localparam logic [63:0] ID_ISAR6_A32_VAL = 64'h0000_0000_0111_1111;
  localparam logic [63:0] ID_ISAR6_A32_NOFP_VAL = 64'h0000_0000_0001_1000;
  localparam logic [63:0] MVFR0_A32_VAL = 64'h0000_0000_1011_0222;
  // QEMU 无 FP：MVFR0/1/2 整体为 0（VFP/NEON 特征描述）。
  localparam logic [63:0] MVFR0_A32_NOFP_VAL = 64'h0;
  localparam logic [63:0] MVFR1_A32_VAL = 64'h0000_0000_1321_1111;
  localparam logic [63:0] MVFR1_A32_NOFP_VAL = 64'h0;
  localparam logic [63:0] MVFR2_A32_VAL = 64'h0000_0000_0000_0043;
  localparam logic [63:0] MVFR2_A32_NOFP_VAL = 64'h0;
  localparam logic [63:0] ID_PFR2_A32_VAL = 64'h0000_0000_0000_0011;
  localparam logic [63:0] ID_MMFR5_A32_VAL = 64'h0000_0000_0000_0002;
  localparam logic [63:0] CLIDR_EL1_VAL = 64'h0000_0000_0000_0123;
  localparam logic [63:0] ID_AA64PFR0_VAL  = 64'h1301_0011_2011_0022;
  // 无 FP/NEON 配置（QEMU -cpu max,vfp=off,neon=off,vfp-d32=off）：
  // ID_AA64PFR0.FP/ASIMD=0xf、ISAR0.FHM=0、ISAR1.FRINTTS=0，
  // MVFR0.SIMDREG=0、MVFR1.SIMDFMAC=0、MVFR2.SIMDMISC=0。
  localparam logic [63:0] ID_AA64PFR0_NOFP_VAL  = 64'h1301_0011_20ff_0022;
  localparam logic [63:0] ID_AA64PFR1_VAL  = 64'h0010_1010_1200_0121;
  localparam logic [63:0] ID_AA64DFR0_VAL  = 64'h1000_0000_1030_560a;
  localparam logic [63:0] ID_AA64DFR1_VAL  = 64'h0000_0000_0000_0000;
  localparam logic [63:0] ID_AA64ISAR0_VAL = 64'h1221_1111_1031_2120;
  // QEMU 无 FP 时按 FEAT 依赖清零（实证抓取）：ISAR0 低 32 位清零 + FHM。
  localparam logic [63:0] ID_AA64ISAR0_NOFP_VAL = 64'h1220_0000_1031_0000;
  localparam logic [63:0] ID_AA64ISAR1_VAL = 64'h0111_2111_1021_1502;
  localparam logic [63:0] ID_AA64ISAR1_NOFP_VAL = 64'h0101_0110_1020_0502;
  localparam logic [63:0] ID_AA64MMFR0_VAL = 64'h2100_0323_1020_1126;
  localparam logic [63:0] ID_AA64MMFR1_VAL = 64'h0110_1120_1031_2122;
  localparam logic [63:0] ID_AA64MMFR2_VAL = 64'h1221_0111_1201_1011;
  localparam logic [63:0] ID_AA64MMFR3_VAL = 64'h1000_0000_1100_1111;
  localparam logic [63:0] ID_AA64ZFR0_VAL  = 64'h0110_1101_0121_0022;
  // QEMU virt `-cpu max`：DCZID_EL0 = 0x4（DZP=0，BS=0 -> dc zva 64B）
  localparam logic [63:0] DCZID_EL0_VAL    = 64'h0000_0000_0000_0004;
  localparam logic [63:0] CTR_EL0_VAL      = 64'h0000_0000_b444_c004;
  localparam logic [63:0] CNTFRQ_EL0_VAL   = 64'h0000_0000_3b9a_ca00;
  /* verilator lint_on UNUSEDPARAM */

  // P7-0 FP state architectural masks. FPCR/FPSR are 32-bit architectural
  // registers; unimplemented/reserved bits are RAZ/WI. CPACR is a 64-bit
  // system register, and P7 owns only FPEN[21:20].
  /* verilator lint_off UNUSEDPARAM */
  localparam logic [63:0] CPACR_P7_OWNED_FPEN_MASK =
      64'h0000_0000_0030_0000;
  localparam logic [31:0] FPCR_P7_WRMASK = 32'h07c8_0000;
  localparam logic [31:0] FPSR_P7_WRMASK = 32'hf800_009f;
  // QEMU syn_a64_fp_access_trap(1, 0xe)：EC(0x07) | IL(1) |
  // FP_ISS.CV(1) | FP_ISS.COND(0xe)，是 AArch64 FP access 的完整 syndrome。
  localparam logic [31:0] ESR_FP_ACCESS_TRAP = 32'h1fe0_0000;
  /* verilator lint_on UNUSEDPARAM */

  // 解码结果（P2 标量核心内部信号）
  typedef struct packed {
    logic         valid;       // 指令被支持
    // P7-1 FP 标量载荷。fp_valid=1 时 fp_rd/fp_rn/fp_rm 均是 V0..V31，
    // 与 GPR rs* 命名空间完全分离；fp_operand_* 是 ID 级 raw snapshot。
    logic         fp_valid;
    fp_op_t       fp_op;
    logic         fp_is_double;
    logic         fp_is_half;        // P7-5：FP16 参与（算术/one-source/FCVT）
    logic         fp_fcvt_dst_half;  // P7-5：FCVT 目的为 H（源为 S/D）
    logic [2:0]   fp_rint_mode;      // P7-5：FRINT 模式（N/P/M/Z/A/X/I）
    logic         fp_wb_we;
    logic [4:0]   fp_rd;
    logic [4:0]   fp_rn;
    logic         fp_rn_en;
    logic [4:0]   fp_rm;
    logic         fp_rm_en;
    logic [127:0] fp_operand_a;
    logic [127:0] fp_operand_b;
    logic         fp_cmp_zero;
    logic         fp_signal_all_nans;
    // P7-4：标量 FMA 第三源（Ra）与转换载荷。
    logic [4:0]   fp_ra;
    logic         fp_ra_en;
    logic [127:0] fp_operand_c;
    logic         fp_conv_to_int;  // 1=FCVTZS/FCVTZU scalar（目的 GPR）
    logic         fp_conv_is_32;   // W 形式：源/目的为 32 位
    logic [6:0]   fp_conv_shift;   // 定点 scale 0..64（整数形式=0）
    logic [63:0]  fp_conv_int;     // 整数/定点 -> FP 的整数源
    // P7-2 Advanced SIMD integer payload. neon_valid also covers the
    // single-Q memory forms so FPEN/trap and memory boundaries share one
    // architectural access bit.
    logic         neon_valid;
    neon_op_t     neon_op;
    logic [1:0]   neon_size;       // 0=B, 1=H, 2=S, 3=D
    logic [6:0]   neon_shift;      // decoded immediate shift amount
    logic         neon_wb_we;
    logic [4:0]   neon_rd;
    logic [4:0]   neon_rn;
    logic [4:0]   neon_rm;
    logic         neon_rn_en;
    logic         neon_rm_en;
    logic [127:0] neon_operand_a;
    logic [127:0] neon_operand_b;
    logic         neon_mem_load;
    // P7-3 vector FP reuses the NEON hazard/trap namespace, while its
    // execution/effect path is distinct from the integer NEON unit.
    logic         neon_fp_valid;
    neon_fp_op_t  neon_fp_op;
    logic         neon_fp_is_double;
    logic         neon_fp_is_half;   // P7-5：4H/8H 向量形状
    logic [2:0]   neon_fp_rint_mode; // P7-5：向量 FRINT 模式
    logic         neon_fp_quad;
    logic         neon_fp_ra_en;   // FMLA/FMLS 读 Vd（addend）
    logic [127:0] neon_fp_operand_c;
    logic         neon_align;
    logic         neon_range;
    alu_op_t      alu_op;
    logic         is_32;
    logic         set_flags;
    logic [63:0]  operand_a;
    logic [63:0]  operand_b;
    logic [63:0]  operand_c;   // MADD 族加数（Ra）
    logic         use_shift;
    logic [1:0]   shift_type;  // 0=LSL 1=LSR 2=ASR
    logic [5:0]   shift_amt;
    logic         inv_b;       // 逻辑取反族（BIC/ORN/EON/BICS/MVN）
    logic [3:0]   ccmp_nzcv;   // CCMP/CCMN 条件不满足时的 NZCV 立即数
    logic         ccmp_taken;  // CCMP/CCMN 条件是否满足（decode 按 NZCV 求值）
    logic [1:0]   wb_sel;      // 0=ALU 1=extra 2=load
    logic         wb_we;
    logic [4:0]   wb_rd;
    logic [63:0]  wb_extra;    // MOV 宽立即数 / BL 链接地址 / ADR 结果
    logic         sp_we;
    logic [63:0]  next_pc;
    logic         is_load;
    logic         is_store;
    logic         mem_unpriv;   // LDTR/STTR：按 EL0 权限访问
    logic         is_pair;      // LDP/STP（第二数据/写回）
    logic         is_ldxr;      // LDXR/LDAXR：提交时记录 exclusive 监视器
    logic         is_stxr;      // STXR/STLXR：排空后读比较写 + 提交时清监视器
    logic         is_clrex;     // CLREX：提交时清监视器
    logic         is_atomic;    // LSE 原子 RMW（P6）
    atomic_op_t   atomic_op;
    logic [63:0]   atomic_cmp;  // CAS 期望值（Rs）；其他原子操作忽略
    logic [63:0]   atomic_cmp2; // CASP 第二个期望值（Rs+1）
    logic [1:0]   mem_size;    // 0=8b 1=16b 2=32b 3=64b
    logic         ldr_sw;      // 有符号 Load（LDRSB/LDRSH/LDRSW）
    logic         ldr_x;       // 1=符号扩展到 64 位（X 形式/LDRSW）；
                               // 0=符号扩展到 32 位再零扩展（W 形式）
    logic [63:0]  mem_addr;
    logic [63:0]  mem_wdata;
    logic [63:0]  mem_wdata2;   // STP 第二写数据
    logic [7:0]   mem_strb;
    logic [4:0]   wb2_rd;       // LDP 第二目标
    logic         wb2_we;
    logic [63:0]  wb2_extra;
    logic         wb3_we;       // pre/post 基址更新（=rn）
    logic [4:0]   wb3_rd;
    logic [63:0]  wb3_extra;
    logic [4:0]   rs1;         // 源寄存器 1（读端口，31 表示 XZR 无读取）
    logic         rs1_en;
    logic [4:0]   rs2;
    logic         rs2_en;
    logic [4:0]   rs3;
    logic         rs3_en;
    logic [4:0]   rs4;
    logic         rs4_en;
    logic [4:0]   rs5;
    logic         rs5_en;
    logic         exc;          // 本指令触发同步异常（ID 级提交）
    logic [31:0]  exc_code;     // ESR.EC
    logic [31:0]  exc_esr;      // 可选完整 ESR（系统寄存器 trap 含 ISS）
    sys_op_t      sys_op;       // ERET/MRS/MSR（SYS_NONE 表示无）
    sys_reg_t     sys_reg;      // 系统寄存器选择
    logic [63:0]  sys_wdata;    // MSR 写数据（读源 GPR）
    logic [63:0]  exc_elr;      // 异常 ELR（SVC=pc+4，分支 IABT=目标，
                                // 其余=pc）
    maint_op_t    maint_op;     // SYS_MAINT 子类型（IC/DC/TLBI）
    logic [63:0]  maint_va;     // 维护地址（Xt 寄存器值，TLBI VAE1IS 忽略）
    logic         maint_write;  // AT S1E1W 写权限探测
    maint_at_regime_t maint_at_regime; // AT 的 E1/E0/E1+PAN 翻译 regime
    // LSE128 预检结果：对齐/物理范围 fault 在任何 Store 前提交。
    logic         atomic_align;
    logic         atomic_range;
  } decoded_insn_t;

  // EX 级以后的流水线载荷（不含 ID 专用的读端口/valid 字段）
  typedef struct packed {
    // P7-1 FP 载荷（在 ID/EX 锁存，避免提交前重新读取 V/FPCR）。
    logic         fp_valid;
    fp_op_t       fp_op;
    logic         fp_is_double;
    logic         fp_is_half;
    logic         fp_fcvt_dst_half;
    logic [2:0]   fp_rint_mode;
    logic         fp_wb_we;
    logic [4:0]   fp_rd;
    logic [127:0] fp_operand_a;
    logic [127:0] fp_operand_b;
    logic         fp_cmp_zero;
    logic         fp_signal_all_nans;
    logic [127:0] fp_operand_c;
    logic         fp_conv_to_int;
    logic         fp_conv_is_32;
    logic [6:0]   fp_conv_shift;
    logic [63:0]  fp_conv_int;
    logic [31:0]  fpcr;
    // P7-2 Advanced SIMD integer payload, locked at ID/EX.
    logic         neon_valid;
    neon_op_t     neon_op;
    logic [1:0]   neon_size;
    logic [6:0]   neon_shift;
    logic         neon_wb_we;
    logic [4:0]   neon_rd;
    logic [127:0] neon_operand_a;
    logic [127:0] neon_operand_b;
    logic         neon_mem_load;
    logic         neon_fp_valid;
    neon_fp_op_t  neon_fp_op;
    logic         neon_fp_is_double;
    logic         neon_fp_is_half;
    logic [2:0]   neon_fp_rint_mode;
    logic         neon_fp_quad;
    logic [127:0] neon_fp_operand_c;
    alu_op_t      alu_op;
    logic         is_32;
    logic         set_flags;
    logic [63:0]  operand_a;
    logic [63:0]  operand_b;
    logic [63:0]  operand_c;
    logic         use_shift;
    logic [1:0]   shift_type;
    logic [5:0]   shift_amt;
    logic         inv_b;
    logic [3:0]   ccmp_nzcv;
    logic         ccmp_taken;
    logic [1:0]   wb_sel;
    logic         wb_we;
    logic [4:0]   wb_rd;
    logic [63:0]  wb_extra;
    logic         sp_we;
    logic [63:0]  next_pc;
    logic         is_load;
    logic         is_store;
    logic         is_pair;
    logic         is_ldxr;
    logic         is_stxr;
    logic         is_clrex;
    logic         is_atomic;
    atomic_op_t   atomic_op;
    logic [63:0]   atomic_cmp;
    logic [63:0]   atomic_cmp2;
    logic [1:0]   mem_size;
    logic         ldr_sw;
    logic         ldr_x;
    logic [63:0]  mem_addr;
    logic [63:0]  mem_wdata;
    logic [63:0]  mem_wdata2;
    logic [7:0]   mem_strb;
    logic [4:0]   wb2_rd;
    logic         wb2_we;
    logic [63:0]  wb2_extra;
    logic         wb3_we;
    logic [4:0]   wb3_rd;
    logic [63:0]  wb3_extra;
    logic [63:0]  mem_paddr;    // 翻译后的物理地址（P5a：MMU 开时有效）
    logic [63:0]  mem_paddr2;   // LSE128 高半物理地址（跨页时独立翻译）
    logic         mem_cacheable;  // 翻译结果是否可缓存（M2-4c，MAIR）
    logic         mem_cacheable2; // LSE128 高半 cache 属性
    sys_op_t      sys_op;       // MRS 定时器读值在 EX 计算（P6）
    sys_reg_t     sys_reg;
  } ex_pipe_t;

  // 提交包：架构状态只在 COMMIT 阶段且 valid=1 的时钟沿更新。
  typedef struct packed {
    logic              valid;       // 本周期有提交
    logic [63:0]       pc;          // 提交指令 PC
    logic [63:0]       next_pc;     // 下一条 PC
    logic [31:0]       insn;        // 指令编码（失败诊断用）
    logic              gpr_we;      // 通用寄存器写回使能
    logic [4:0]        gpr_rd;      // 写回寄存器编号（Rd=31 视为 XZR，写回无效）
    logic [63:0]       gpr_wdata;   // 写回数据
    logic              gpr2_we;     // 第二写回（LDP rt2）
    logic [4:0]        gpr2_rd;
    logic [63:0]       gpr2_wdata;
    logic              gpr3_we;     // 第三写回（pre/post 基址）
    logic [4:0]        gpr3_rd;
    logic [63:0]       gpr3_wdata;
    logic              sp_we;       // SP 写回使能
    logic [63:0]       sp_wdata;    // SP 写回数据
    logic              nzcv_we;     // NZCV 更新使能
    logic [3:0]        nzcv;        // bit3=N bit2=Z bit1=C bit0=V
    logic              mem_we;      // 内存写使能
    logic [63:0]       mem_addr;    // 内存写地址
    logic [63:0]       mem_wdata;   // 内存写数据
    logic [7:0]        mem_strb;    // 字节写使能，bit[i] 对应 addr+i
    logic              mem2_we;     // 第二存储（STP）
    logic [63:0]       mem2_addr;
    logic [63:0]       mem2_wdata;
    logic [7:0]        mem2_strb;
    logic              exc_valid;   // 异常提交
    logic [31:0]       exc_code;    // 异常编码，见 exc_code_t
    logic [31:0]       exc_esr;     // 完整 ESR（EC<<26|ISS，含 IL）
    logic [63:0]       exc_far;     // FAR_EL1（abort 类；其余保持不变）
    logic              mon_we;      // exclusive 监视器被本提交更新
    logic              mon_valid;   // 更新后的有效性（1=记录 LDXR 地址/值）
    logic [63:0]       mon_addr;    // LDXR 记录的地址（clean VA）
    logic [63:0]       mon_data;    // LDXR 记录的值（与 QEMU exclusive_val 一致）
    logic [63:0]       mon_data2;   // LDXP 记录的高 64 位（exclusive_high）
    // P7-0：追加的 RTL-only FP effect 视图。它与既有 scalar 字段同属一条
    // commit.valid；QEMU FP_COMMIT wire 不携带这些 effect 位（协议只比较
    // raw state delta）。追加字段不改变前面的 scalar layout。
    logic [2:0]        vec_write_count; // 0..4，P7-0 测试边界
    logic [4:0]        vec_rd0;
    logic [4:0]        vec_rd1;
    logic [4:0]        vec_rd2;
    logic [4:0]        vec_rd3;
    logic [127:0]      vec_wdata0;
    logic [127:0]      vec_wdata1;
    logic [127:0]      vec_wdata2;
    logic [127:0]      vec_wdata3;
    logic              fpcr_we;
    logic [31:0]       fpcr_wdata;
    logic              fpsr_we;
    logic [31:0]       fpsr_wdata;
  } commit_packet_t;

  // ---- M1-B：统一内存 request/response 协议 ----
  // 取指、数据访问、页表遍历共用同一组 valid/ready 信号：
  //   req_valid/req_addr/req_we/req_strb/req_wdata -> req_accept（从端接收）
  //   rsp_valid/rsp_rdata/rsp_fault <- rsp_ready（主端消费）
  // 请求被 req_accept 接收后，从端保证返回一次 rsp_valid；响应可能
  // 延迟任意周期（SRAM/Cache/延迟注入器共享此接口）。
  typedef struct packed {
    logic [63:0] addr;
    logic        we;        // 1=写 0=读
    logic [7:0]  strb;      // 字节使能（写）
    logic [63:0] wdata;     // 写数据
    maint_op_t   maint;     // 维护操作（NONE=普通访存，M2-4b）
    logic        bypass;    // 1=旁路 L1/L2（Device/不可缓存，M2-4c）；
                            // 0=正常缓存路径
  } mem_req_t;

  typedef struct packed {
    logic [63:0] rdata;     // 读数据（写请求返回旧值或 0，语义未定义）
    logic        fault;     // 地址越界/访问失败
  } mem_rsp_t;

// lcvex_mem_arb.sv
// M1-B：内存端口仲裁器（单 outstanding）。
// 端口优先级：0=PTW（最高）> 1=数据 > 2=取指（最低）。
// 请求被下游接受后进入 in_flight，响应按选中的端口路由回请求方；
// in_flight 期间不再接受新请求（响应消费后恢复）。

`timescale 1ns/1ps

module lcvex_mem_arb #(
    parameter int PORTS = 3
) (
    input  logic                    clk,
    input  logic                    rst_n,
    // 请求端口（0=PTW 1=数据 2=取指）
    input  logic [PORTS-1:0]        req_valid,
    input  mem_req_t [PORTS-1:0] req,
    output logic [PORTS-1:0]        req_ready,
    // 响应端口
    output logic [PORTS-1:0]        rsp_valid,
    output mem_rsp_t [PORTS-1:0] rsp,
    input  logic [PORTS-1:0]        rsp_ready,
    // 下游（SRAM / 延迟注入器）
    output logic                    mem_req_valid,
    output mem_req_t     mem_req,
    input  logic                    mem_req_accept,
    input  logic                    mem_rsp_valid,
    input  mem_rsp_t     mem_rsp,
    output logic                    mem_rsp_ready
);

  logic        in_flight;
  logic [$clog2(PORTS)-1:0] sel_r;

  // 优先级编码：取最高优先级的有效请求
  function automatic logic [$clog2(PORTS)-1:0] prio_sel(input logic [PORTS-1:0] v);
    logic found;
    begin
      prio_sel = '0;
      found = 1'b0;
      for (int i = 0; i < PORTS; i++) begin
        if (!found && v[i]) begin
          prio_sel = i[$clog2(PORTS)-1:0];  // 最低索引 = 最高优先级
          found = 1'b1;
        end
      end
    end
  endfunction

  logic [$clog2(PORTS)-1:0] sel_comb;
  assign sel_comb = prio_sel(req_valid);

  // 空闲且无 in_flight：把最高优先级请求呈现给下游
  assign mem_req_valid = !in_flight && (|req_valid);
  assign mem_req       = req[sel_comb];

  // 请求接受：只有被选中的端口看到 ready
  always_comb begin
    req_ready = '0;
    if (mem_req_valid && mem_req_accept) begin
      req_ready[sel_comb] = 1'b1;
    end
  end

  // 响应：路由到 in_flight 的端口
  assign rsp_valid = (in_flight && mem_rsp_valid) ? (3'b001 << sel_r) : 3'b000;
  assign rsp[0] = (in_flight && mem_rsp_valid && sel_r == 2'd0) ? mem_rsp : '0;
  assign rsp[1] = (in_flight && mem_rsp_valid && sel_r == 2'd1) ? mem_rsp : '0;
  assign rsp[2] = (in_flight && mem_rsp_valid && sel_r == 2'd2) ? mem_rsp : '0;
  assign mem_rsp_ready = in_flight && mem_rsp_valid && rsp_ready[sel_r];

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      in_flight <= 1'b0;
      sel_r     <= '0;
    end else begin
      if (!in_flight && mem_req_valid && mem_req_accept) begin
        in_flight <= 1'b1;
        sel_r     <= sel_comb;
      end
      if (mem_rsp_ready) begin
        in_flight <= 1'b0;
      end
    end
  end

endmodule
